import { test, describe, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written double of the pricing dependency (priceOf(sku) -> euros).
const prices = { A: 10, B: 25.5, C: 0.1, D: 33.33, BIG: 1000 }
const calls = []
const pricing = { async priceOf(sku) { calls.push(sku); return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const totalOf = async (items) => {
  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

describe('POST /orders', () => {
  test('201 with id, items echoed and total; JSON content type', async () => {
    const items = [{ sku: 'A', qty: 2 }]
    const res = await post({ items })
    assert.equal(res.status, 201)
    assert.equal(res.headers.get('content-type'), 'application/json')
    const body = await res.json()
    assert.deepEqual(body, { id: body.id, items, total: 20 })
    assert.equal(typeof body.id, 'string')
  })

  test('ids are sequential strings', async () => {
    const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
    const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
    assert.equal(Number(b.id), Number(a.id) + 1)
  })

  test('price is looked up once per line item, in order', async () => {
    calls.length = 0
    await totalOf([{ sku: 'A', qty: 1 }, { sku: 'B', qty: 1 }, { sku: 'A', qty: 1 }])
    assert.deepEqual(calls, ['A', 'B', 'A'])
  })

  test('total sums price * qty across items', async () => {
    assert.equal(await totalOf([{ sku: 'A', qty: 3 }, { sku: 'B', qty: 2 }]), 81)
  })

  test('total is floored, not rounded', async () => {
    // CHARACTERIZATION: current behaviour may be unintended — fractional euros are truncated (19.9 -> 19), so cents are lost
    assert.equal(await totalOf([{ sku: 'D', qty: 1 }]), 33)
    assert.equal(await totalOf([{ sku: 'B', qty: 1 }, { sku: 'A', qty: 1 }]), 35)
    assert.equal(await totalOf([{ sku: 'A', qty: 1 }, { sku: 'C', qty: 9 }]), 10)
  })

  describe('discount', () => {
    test('exactly 100 gets no discount', async () => {
      assert.equal(await totalOf([{ sku: 'A', qty: 10 }]), 100)
    })

    test('just above 100 gets 10% off, then floored', async () => {
      // CHARACTERIZATION: current behaviour may be unintended — 100.5 -> 90.45 -> 90; crossing the threshold makes the order cheaper than a 100 order (100)
      assert.equal(await totalOf([{ sku: 'A', qty: 10 }, { sku: 'C', qty: 5 }]), 90)
      assert.equal(await totalOf([{ sku: 'A', qty: 11 }]), 99)
    })

    test('large orders get a flat 10%, with no further tiers', async () => {
      // CHARACTERIZATION: current behaviour may be unintended — one flat rate regardless of size
      assert.equal(await totalOf([{ sku: 'BIG', qty: 1 }]), 900)
      assert.equal(await totalOf([{ sku: 'BIG', qty: 10 }]), 9000)
      assert.equal(await totalOf([{ sku: 'BIG', qty: 1000 }]), 900000)
    })

    test('discount is applied to the whole order total, then floored', async () => {
      // 3 * 33.33 = 99.99 (no discount, 99); 4 * 33.33 = 133.32 -> 119.988 -> 119
      assert.equal(await totalOf([{ sku: 'D', qty: 3 }]), 99)
      assert.equal(await totalOf([{ sku: 'D', qty: 4 }]), 119)
    })
  })

  describe('invalid input', () => {
    for (const [name, body, raw] of [
      ['missing items', {}],
      ['empty items', { items: [] }],
      ['items not an array', { items: 'A' }],
      ['malformed JSON', undefined, '{nope'],
    ]) {
      test(`400 for ${name}`, async () => {
        const res = await post(body, raw)
        assert.equal(res.status, 400)
        assert.deepEqual(await res.json(), { error: 'items required' })
      })
    }

    test('empty body is 400', async () => {
      const res = await post(undefined, '')
      assert.equal(res.status, 400)
    })

    test('unknown sku (no price) yields a null total but still 201', async () => {
      // CHARACTERIZATION: current behaviour may be unintended — undefined price -> NaN -> JSON null, no validation
      const res = await post({ items: [{ sku: 'NOPE', qty: 1 }] })
      assert.equal(res.status, 201)
      assert.equal((await res.json()).total, null)
    })

    test('missing qty yields a null total but still 201', async () => {
      // CHARACTERIZATION: current behaviour may be unintended — qty undefined -> NaN, no validation
      const res = await post({ items: [{ sku: 'A' }] })
      assert.equal(res.status, 201)
      assert.equal((await res.json()).total, null)
    })

    test('negative qty is accepted', async () => {
      // CHARACTERIZATION: current behaviour may be unintended — no qty validation; Math.floor(-10) = -10
      assert.equal(await totalOf([{ sku: 'A', qty: -1 }]), -10)
    })
  })
})

describe('GET /orders/:id', () => {
  test('returns the stored order', async () => {
    const created = await (await post({ items: [{ sku: 'BIG', qty: 1 }] })).json()
    const res = await fetch(`${base}/orders/${created.id}`)
    assert.equal(res.status, 200)
    assert.equal(res.headers.get('content-type'), 'application/json')
    assert.deepEqual(await res.json(), created)
  })

  test('unknown id is 200 with an error body', async () => {
    // CHARACTERIZATION: current behaviour may be unintended — "not found" answered with status 200, not 404
    const res = await fetch(`${base}/orders/does-not-exist`)
    assert.equal(res.status, 200)
    assert.deepEqual(await res.json(), { error: 'not found' })
  })
})

describe('other routes', () => {
  test('unknown path is 404 no route', async () => {
    const res = await fetch(`${base}/nope`)
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  })

  test('wrong method on /orders is 404 no route', async () => {
    const res = await fetch(`${base}/orders`)
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  })

  test('nested path under /orders/:id is 404', async () => {
    const res = await fetch(`${base}/orders/1/items`)
    assert.equal(res.status, 404)
  })
})
EOF
